			if (pyObject != null)
			{
				return new LiteralNode(pyObject, f, token3.startIndex, token3.startIndex + token3.value.Length);
			}
			return new ValueNode(token3.value, f, token3.startIndex, token3.startIndex + token3.value.Length);
